rame.BackgroundTransparency=0.05 MainFrame.BorderSizePixel=0 MainFrame.ZIndex=2 MainFrame.Parent=MainContainer Instance.new("UICorner",MainFrame).CornerRadius=UDim.new(0,12)local Title=Instance.new("TextLabel")Title.Size=UDim2.new(1,-35,0,30)Title.Position=UDim2.new(0,12,0,2)Title.BackgroundTransparency=1 Title.Text="TUNE"Title.TextColor3=Color3.fromRGB(255,255,255)Title.TextSize=14 Title.Font=Enum.Font.SourceSansBold Title.TextXAlignment=Enum.TextXAlignment.Left Title.ZIndex=3 Title.Parent=MainFrame local ToggleBtn=Instance.new("TextButton")ToggleBtn.Size=UDim2.new(0,22,0,22)ToggleBtn.Position=UDim2.new(1,-28,0,6)ToggleBtn.BackgroundColor3=Color3.fromRGB(0,0,0)ToggleBtn.BackgroundTransparency=0.5 ToggleBtn.Text="-"ToggleBtn.TextColor3=Color3.fromRGB(255,255,255)ToggleBtn.TextSize=14 ToggleBtn.Font=Enum.Font.SourceSansBold ToggleBtn.ZIndex=3 ToggleBtn.Parent=MainFrame Instance.new("UICorner",ToggleBtn).CornerRadius=UDim.new(0,6)local OpenIcon=Instance.new("TextButton")OpenIcon.Name="OpenIconBtn"OpenIcon.Size=UDim2.new(0,44,0,44)OpenIcon.Position=UDim2.new(0,15,0.4,0)OpenIcon.BackgroundColor3=Color3.fromRGB(18,18,18)OpenIcon.BackgroundTransparency=0.1 OpenIcon.Text="T"OpenIcon.TextColor3=Color3.fromRGB(255,255,255)OpenIcon.TextSize=22 OpenIcon.Font=Enum.Font.SourceSansBold OpenIcon.Visible=false OpenIcon.Active=true OpenIcon.Draggable=true OpenIcon.ZIndex=10 OpenIcon.Parent=ScreenGui Instance.new("UICorner",OpenIcon).CornerRadius=UDim.new(1,0)local IconStroke=Instance.new("UIStroke")IconStroke.Thickness=2.5 IconStroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border IconStroke.Color=Color3.fromRGB(255,255,255)IconStroke.Parent=OpenIcon local IconGradient=Instance.new("UIGradient")IconGradient.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(0,0,0)),ColorSequenceKeypoint.new(0.2,Color3.fromRGB(255,255,255)),ColorSequenceKeypoint.new(0.4,Color3.fromRGB(0,0,0)),ColorSequenceKeypoint.new(0.7,Color3.fromRGB(255,255,255)),ColorSequenceKeypoint.new(1,Color3.fromRGB(0,0,0))})IconGradient.Rotation=0 IconGradient.Parent=IconStroke ToggleBtn.MouseButton1Click:Connect(function()MainContainer.Visible=false OpenIcon.Visible=true end)OpenIcon.MouseButton1Click:Connect(function()MainContainer.Visible=true OpenIcon.Visible=false end)local currentAngle=0 local pulseTimer=0 RunService.RenderStepped:Connect(function(deltaTime)currentAngle=(currentAngle+(deltaTime*160))%360 if GlowGradient and GlowGradient.Parent then GlowGradient.Rotation=currentAngle end if IconGradient and IconGradient.Parent then IconGradient.Rotation=currentAngle end if OpenIcon and OpenIcon.Visible then pulseTimer=pulseTimer+(deltaTime*4)local brightness=(math.sin(pulseTimer)+1)/2 local val=180+math.floor(brightness*75)OpenIcon.TextColor3=Color3.fromRGB(val,val,val)end end)local Container=Instance.new("Frame")Container.Size=UDim2.new(1,-16,1,-38)Container.Position=UDim2.new(0,8,0,32)Container.BackgroundTransparency=1 Container.ZIndex=3 Container.Parent=MainFrame local UIListLayout=Instance.new("UIListLayout")UIListLayout.Padding=UDim.new(0,6)UIListLayout.SortOrder=Enum.SortOrder.LayoutOrder UIListLayout.Parent=Container local function createValueAdjuster(titleText,settingKey,step,order)local frame=Instance.new("Frame")frame.Size=UDim2.new(1,0,0,28)frame.BackgroundTransparency=1 frame.LayoutOrder=order frame.ZIndex=3 frame.Parent=Container local label=Instance.new("TextLabel")label.Size=UDim2.new(0.52,0,1,0)label.Position=UDim2.new(0,4,0,0)label.BackgroundTransparency=1 label.Text=titleText label.TextColor3=Color3.fromRGB(240,240,240)label.TextSize=12 label.Font=Enum.Font.SourceSansBold label.TextXAlignment=Enum.TextXAlignment.Left label.ZIndex=4 label.Parent=frame local minusBtn=Instance.new("TextButton")minusBtn.Size=UDim2.new(0,20,0,20)minusBtn.Position=UDim2.new(1,-74,0.5,-10)minusBtn.BackgroundColor3=Color3.fromRGB(30,30,30)minusBtn.BackgroundTransparency=0.2 minusBtn.Text="-"minusBtn.TextColor3=Color3.fromRGB(255,255,255)minusBtn.Font=Enum.Font.SourceSansBold minusBtn.ZIndex=4 minusBtn.Parent=frame local textBox=Instance.new("TextBox")textBox.Size=UDim2.new(0,30,0,20)textBox.Position=UDim2.new(1,-50,0.5,-10)textBox.BackgroundColor3=Color3.fromRGB(10,10,10)textBox.BackgroundTransparency=0.2 textBox.Text=string.format("%.1f",TUNE_SETTINGS[settingKey])textBox.TextColor3=Color3.fromRGB(255,255,255)textBox.TextSize=12 textBox.Font=Enum.Font.SourceSansBold textBox.ClearTextOnFocus=false textBox.ZIndex=4 textBox.Parent=frame local plusBtn=Instance.new("TextButton")plusBtn.Size=UDim2.new(0,20,0,20)plusBtn.Position=UDim2.new(1,-16,0.5,-10)plusBtn.BackgroundColor3=Color3.fromRGB(30,30,30)plusBtn.BackgroundTransparency=0.2 plusBtn.Text="+"plusBtn.TextColor3=Color3.fromRGB(255,255,255)plusBtn.Font=Enum.Font.SourceSansBold plusBtn.ZIndex=4 plusBtn.Parent=frame Instance.new("UICorner",minusBtn).CornerRadius=UDim.new(0,4)Instance.new("UICorner",textBox).CornerRadius=UDim.new(0,4)Instance.new("UICorner",plusBtn).CornerRadius=UDim.new(0,4)local function updateValue(newVal)newVal=math.max(1,newVal)TUNE_SETTINGS[settingKey]=newVal textBox.Text=string.format("%.1f",newVal)end minusBtn.MouseButton1Click:Connect(function()updateValue(TUNE_SETTINGS[settingKey]-step)end)plusBtn.MouseButton1Click:Connect(function()updateValue(TUNE_SETTINGS[settingKey]+step)end)textBox.FocusLost:Connect(function()local num=tonumber(textBox.Text)if num then updateValue(num)else textBox.Text=string.format("%.1f",TUNE_SETTINGS[settingKey])end end)end local function tuneVehicle(vehicle)if not vehicle or vehicle:FindFirstChild("AlreadyECUTuned")then return end local tag=Instance.new("BoolValue")tag.Name="AlreadyECUTuned"tag.Parent=vehicle for _,obj in ipairs(vehicle:GetDescendants())do if obj:IsA("NumberValue")or obj:IsA("IntValue")then local name=obj.Name:lower()if name:find("torque")or name:find("accel")or name:find("horsepower")or name:find("power")or name:find("force")then obj.Value=obj.Value*TUNE_SETTINGS.TorqueMultiplier elseif name:find("rev")or name:find("rpm")or name:find("redline")then obj.Value=obj.Value*TUNE_SETTINGS.RevLimitBoost end end if obj:IsA("VehicleSeat")then obj.Torque=obj.Torque*TUNE_SETTINGS.TorqueMultiplier end end for attrName,attrValue in pairs(vehicle:GetAttributes())do if type(attrValue)=="number"then local name=attrName:lower()if name:find("torque")or name:find("accel")or name:find("power")or name:find("force")then vehicle:SetAttribute(attrName,attrValue*TUNE_SETTINGS.TorqueMultiplier)end end end end createValueAdjuster("แรงบิด/อัตราเร่ง","TorqueMultiplier",0.2,1)createValueAdjuster("รอบเครื่องยนต์","RevLimitBoost",0.2,2)local ManualBtn=Instance.new("TextButton")ManualBtn.Size=UDim2.new(1,0,0,28)ManualBtn.BackgroundColor3=Color3.fromRGB(255,120,0)ManualBtn.BackgroundTransparency=0.1 ManualBtn.Text="จูนรถคันนี้ทันที"ManualBtn.TextColor3=Color3.fromRGB(255,255,255)ManualBtn.TextSize=12 ManualBtn.Font=Enum.Font.SourceSansBold ManualBtn.LayoutOrder=3 ManualBtn.ZIndex=4 ManualBtn.Parent=Container Instance.new("UICorner",ManualBtn).CornerRadius=UDim.new(0,8)ManualBtn.MouseButton1Click:Connect(function()local char=player.Character if char then local humanoid=char:FindFirstChildOfClass("Humanoid")if humanoid and humanoid.SeatPart then local vehicle=humanoid.SeatPart:FindFirstAncestorOfClass("Model")or humanoid.SeatPart.Parent if vehicle then local oldTag=vehicle:FindFirstChild("AlreadyECUTuned")if oldTag then oldTag:Destroy()end tuneVehicle(vehicle)end end end end)local InfoLabel=Instance.new("TextLabel")InfoLabel.Size=UDim2.new(1,0,0,38)InfoLabel.BackgroundTransparency=1 InfoLabel.Text="วิธีใช้งาน: เลือกว่าจะจูนอะไรเท่าไหนก่อนแล้วก็กดจูนรถคันนี้ทันที แล้วเสกรถออกมา"InfoLabel.TextColor3=Color3.fromRGB(200,200,200)InfoLabel.TextSize=10 InfoLabel.Font=Enum.Font.SourceSans InfoLabel.TextWrapped=true InfoLabel.TextYAlignment=Enum.TextYAlignment.Top InfoLabel.LayoutOrder=4 InfoLabel.ZIndex=4 InfoLabel.Parent=Container local function onCharacterAdded(char)local humanoid=char:WaitForChild("Humanoid",10)if humanoid then humanoid.Seated:Connect(function(isSeated,seat)if isSeated and seat then local vehicle=seat:FindFirstAncestorOfClass("Model")or seat.Parent if vehicle then tuneVehicle(vehicle)end end end)end end if player.Character then onCharacterAdded(player.Character)end player.CharacterAdded:Connect(onCharacterAdded)
